// ===================== Small exporters — art + scenes 00–09 =====================
const factB=(x,y,s=1,c='#64748b')=>`<g transform="translate(${x} ${y}) scale(${s})"><rect x="150" y="-170" width="46" height="120" fill="${c}"/><path d="M-200 60 V-60 L-120 -110 V-60 L-40 -110 V-60 L40 -110 V-60 L120 -110 V-60 L200 -110 V60Z" fill="${c}"/>${[-150,-70,10,90].map(v=>`<rect x="${v}" y="-30" width="50" height="40" rx="6" fill="#e2e8f0"/>`).join('')}<rect x="-220" y="60" width="440" height="16" rx="8" fill="#475569"/><circle cx="185" cy="-200" r="22" fill="#cbd5e1"/><circle cx="215" cy="-235" r="28" fill="#e2e8f0"/></g>`;
const kantha=(x,y,w,h,c=C.r,c2=C.y)=>`<g><rect x="${x}" y="${y}" width="${w}" height="${h}" rx="14" fill="#fff6e8" stroke="${c}" stroke-width="8"/><rect x="${x+16}" y="${y+16}" width="${w-32}" height="${h-32}" rx="8" fill="none" stroke="${c}" stroke-width="3" stroke-dasharray="8 7"/>
 <circle cx="${x+w/2}" cy="${y+h/2}" r="${Math.min(w,h)*.2}" fill="none" stroke="${c}" stroke-width="5"/>${[0,1,2,3,4,5,6,7].map(i=>{const a=i*Math.PI/4,r=Math.min(w,h)*.2;return `<ellipse cx="${x+w/2+Math.cos(a)*r*1.45}" cy="${y+h/2+Math.sin(a)*r*1.45}" rx="${r*.32}" ry="${r*.16}" fill="${i%2?c2:c}" transform="rotate(${i*45} ${x+w/2+Math.cos(a)*r*1.45} ${y+h/2+Math.sin(a)*r*1.45})"/>`}).join('')}
 <circle cx="${x+w/2}" cy="${y+h/2}" r="${Math.min(w,h)*.07}" fill="${c2}"/>${[[.15,.18],[.85,.18],[.15,.82],[.85,.82]].map(([a,b])=>`<path d="M${x+w*a-14} ${y+h*b} h28 M${x+w*a} ${y+h*b-14} v28" stroke="${C.g}" stroke-width="5" stroke-linecap="round"/>`).join('')}</g>`;
const honey=(x,y,s=1)=>`<g transform="translate(${x} ${y}) scale(${s})"><rect x="-58" y="-112" width="116" height="34" rx="8" fill="#7c4a12"/><path d="M-70 -78 H70 Q84 -78 84 -60 V70 Q84 96 58 96 H-58 Q-84 96 -84 70 V-60 Q-84 -78 -70 -78Z" fill="#f2a705"/><path d="M-84 -20 H84 V40 H-84Z" fill="#fff8e1"/>${tx(0,22,'মধু',40,'#7c4a12',800)}<path d="M-60 -60 Q-66 -20 -60 10" stroke="#ffe08a" stroke-width="10" stroke-linecap="round" fill="none"/></g>`;
const basket=(x,y,s=1)=>`<g transform="translate(${x} ${y}) scale(${s})"><path d="M-60 -20 Q0 -110 60 -20" fill="none" stroke="#8a6a2a" stroke-width="12"/><path d="M-90 -20 H90 L70 80 H-70Z" fill="#d6b56a"/>${[0,1,2,3].map(i=>`<path d="M-86 ${i*25} H86" stroke="#a8843c" stroke-width="6"/>`).join('')}${[-50,-15,20,55].map(v=>`<path d="M${v} -20 L${v*.8} 80" stroke="#a8843c" stroke-width="5"/>`).join('')}</g>`;
const parcel=(x,y,s=1,c='#d9a55c')=>`<g transform="translate(${x} ${y}) scale(${s})"><rect x="-60" y="-45" width="120" height="90" rx="8" fill="${c}"/><rect x="-60" y="-45" width="120" height="22" fill="#b9853d"/><rect x="-10" y="-45" width="20" height="90" fill="#f5e1b8"/><rect x="18" y="5" width="34" height="24" rx="3" fill="#fff"/></g>`;
const ukflag=(x,y,w=120)=>{const h=w*.6;return `<g><rect x="${x}" y="${y}" width="${w}" height="${h}" fill="#1f3a93"/><path d="M${x} ${y} L${x+w} ${y+h} M${x+w} ${y} L${x} ${y+h}" stroke="#fff" stroke-width="${h*.18}"/><path d="M${x} ${y} L${x+w} ${y+h} M${x+w} ${y} L${x} ${y+h}" stroke="#d52b1e" stroke-width="${h*.07}"/><path d="M${x+w/2} ${y} V${y+h} M${x} ${y+h/2} H${x+w}" stroke="#fff" stroke-width="${h*.3}"/><path d="M${x+w/2} ${y} V${y+h} M${x} ${y+h/2} H${x+w}" stroke="#d52b1e" stroke-width="${h*.16}"/></g>`};
const womanMini=(x,y,c)=>`<g><circle cx="${x}" cy="${y}" r="15" fill="#b07a52"/><path d="M${x-16} ${y-4} Q${x} ${y-26} ${x+16} ${y-4}" fill="#1c1917"/><path d="M${x-22} ${y+46} Q${x-22} ${y+16} ${x} ${y+16} Q${x+22} ${y+16} ${x+22} ${y+46}Z" fill="${c}"/></g>`;
function phoneStore(x,y,w,h,P){return `${phone(x,y,w,h)}<rect x="${x+18}" y="${y+60}" width="${w-36}" height="70" fill="${C.t}"/>${lat(x+w/2,y+106,'Online Store',28,'#fff',800)}${kantha(x+40,y+150,w-80,w-120,C.r,C.y)}${lat(x+50,y+w+60,'Nakshi Kantha',26,C.ink,800,'start')}${lat(x+50,y+w+100,'$ 85',30,C.g,800,'start')}<g data-k="${P}buy">${card(x+40,y+h-150,w-80,70,C.o,35)}${lat(x+w/2,y+h-104,'Buy now',30,'#fff',800)}</g>`}

